import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/theme/catus_theme.dart';class EmergencyScreen extends ConsumerStatefulWidget {  const EmergencyScreen({super.key});  @override  ConsumerState<EmergencyScreen> createState() => _EmergencyScreenState();}class _EmergencyScreenState extends ConsumerState<EmergencyScreen> {  bool _isActivating = false;  bool _sosActive = false;  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: CatusTheme.background,      appBar: AppBar(        title: const Text('Emergency'),        backgroundColor: CatusTheme.background,        elevation: 0,      ),      body: ListView(        padding: const EdgeInsets.all(16),        children: [          _buildSOSButton(),          const SizedBox(height: 24),          _buildEmergencyOptions(),          const SizedBox(height: 24),          _buildEmergencyContacts(),        ],      ),    );  }  Widget _buildSOSButton() {    return Container(      padding: const EdgeInsets.all(24),      decoration: CatusTheme.glassDecoration(borderRadius: 20),      child: Column(        children: [          GestureDetector(            onLongPress: _triggerSOS,            child: AnimatedContainer(              duration: const Duration(milliseconds: 200),              width: _sosActive ? 180 : 160,              height: _sosActive ? 180 : 160,              decoration: BoxDecoration(                shape: BoxShape.circle,                color: _sosActive                    ? CatusTheme.sosRed                    : CatusTheme.sosRed.withValues(alpha: 0.8),                boxShadow: _sosActive                    ? [                        BoxShadow(                            color: CatusTheme.sosRed.withValues(alpha: 0.5),                            blurRadius: 30,                            spreadRadius: 10)                      ]                    : null,              ),              child: Column(                mainAxisAlignment: MainAxisAlignment.center,                children: [                  Icon(_sosActive ? Icons.warning : Icons.emergency,                      size: 48, color: Colors.white),                  const SizedBox(height: 8),                  Text(                    _sosActive ? 'SOS ACTIVE' : 'SOS',                    style: const TextStyle(                      color: Colors.white,                      fontSize: 24,                      fontWeight: FontWeight.bold,                    ),                  ),                ],              ),            ),          ),          const SizedBox(height: 16),          Text(            _sosActive ? 'Hold to cancel' : 'Hold to activate',            style: const TextStyle(color: CatusTheme.textMuted),          ),          if (_sosActive) ...[            const SizedBox(height: 8),            TextButton(              onPressed: _cancelSOS,              child: const Text('Cancel SOS',                  style: TextStyle(color: CatusTheme.sosRed)),            ),          ],        ],      ),    );  }  Widget _buildEmergencyOptions() {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Text('Quick Actions', style: CatusTheme.heading3),        const SizedBox(height: 12),        Row(          children: [            Expanded(                child: _buildQuickAction(                    Icons.volume_up, 'Loud Alert', CatusTheme.sosRed, () {})),            const SizedBox(width: 12),            Expanded(                child: _buildQuickAction(Icons.flashlight_on, 'Flashlight',                    CatusTheme.warningYellow, () {})),          ],        ),        const SizedBox(height: 12),        Row(          children: [            Expanded(                child: _buildQuickAction(Icons.share_location, 'Share Location',                    CatusTheme.safeGreen, () {})),            const SizedBox(width: 12),            Expanded(                child: _buildQuickAction(Icons.record_voice_over, 'Voice Memo',                    CatusTheme.accent, () {})),          ],        ),      ],    );  }  Widget _buildQuickAction(      IconData icon, String label, Color color, VoidCallback onTap) {    return GestureDetector(      onTap: onTap,      child: Container(        padding: const EdgeInsets.all(20),        decoration: CatusTheme.glassDecoration(borderRadius: 16),        child: Column(          children: [            Container(              width: 48,              height: 48,              decoration: BoxDecoration(                  color: color.withValues(alpha: 0.2), shape: BoxShape.circle),              child: Icon(icon, color: color),            ),            const SizedBox(height: 8),            Text(label, style: const TextStyle(fontWeight: FontWeight.bold)),          ],        ),      ),    );  }  Widget _buildEmergencyContacts() {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Row(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            Text('Emergency Contacts', style: CatusTheme.heading3),            IconButton(              icon: const Icon(Icons.add_circle_outline,                  color: CatusTheme.accent),              onPressed: () {},            ),          ],        ),        const SizedBox(height: 12),        Container(          padding: const EdgeInsets.all(16),          decoration: CatusTheme.glassDecoration(borderRadius: 16),          child: Column(            children: [              _buildContactTile(                  Icons.local_police, 'Emergency Services', '911'),              const Divider(),              _buildContactTile(                  Icons.contact_phone, 'Primary Contact', 'Tap to set'),              const Divider(),              _buildContactTile(                  Icons.contact_phone, 'Secondary Contact', 'Tap to set'),            ],          ),        ),      ],    );  }  Widget _buildContactTile(IconData icon, String name, String number) {    return ListTile(      contentPadding: EdgeInsets.zero,      leading: Container(        width: 40,        height: 40,        decoration: BoxDecoration(            color: CatusTheme.accent.withValues(alpha: 0.2),            borderRadius: BorderRadius.circular(8)),        child: Icon(icon, color: CatusTheme.accent),      ),      title: Text(name),      subtitle:          Text(number, style: const TextStyle(color: CatusTheme.textMuted)),      trailing: const Icon(Icons.phone, color: CatusTheme.safeGreen),    );  }  void _triggerSOS() async {    setState(() => _isActivating = true);    await Future.delayed(const Duration(seconds: 2));    setState(() {      _isActivating = false;      _sosActive = true;    });  }  void _cancelSOS() {    setState(() => _sosActive = false);  }}